using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Text;using System.Threading;using System.Collections.Generic;using System.Windows.Forms;
namespace GearLab {
 static class PrintTests {
  static int checks;static void Check(bool ok,string message){checks++;if(!ok)throw new Exception(message);}
  public static int Ui(string folder){Directory.CreateDirectory(folder);var report=new StringBuilder();try{using(var form=new MainForm(new TestDialogs()))form.ReleaseRegression(folder,report);File.WriteAllText(Path.Combine(folder,"ui-results.txt"),report.ToString());return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"ui-error.txt"),ex.ToString());return 1;}}
  public static int Run(string folder){Directory.CreateDirectory(folder);var log=new StringBuilder();try{
   for(int kind=0;kind<4;kind++){var p=Engine.Starter(kind);p.IntegratedRing=kind==0;var r=Engine.Calculate(p);r.Model=CadBuilder.Build(r);Check(r.Valid&&r.Model.Valid,"default print CAD "+kind+": "+string.Join(";",r.Model.Errors));var parts=PrintExport.Select(r.Model,null);Check(parts.Parts.All(PrintExport.Candidate)&&parts.Parts.All(q=>!q.Reference&&q.Role!="bearing"&&q.Role!="fastener"),"print excludes purchases");bool rejected=false;try{PrintExport.Select(r.Model,new string[0]);}catch{rejected=true;}Check(rejected,"empty selection blocked");PrintExport.Zip(parts,Path.Combine(folder,"print-"+kind+".zip"));StepExport.Write(parts,Path.Combine(folder,"print-"+kind+".step"));ReleaseSupport.WriteText(Path.Combine(folder,"print-"+kind+".gear.json"),ReleaseSupport.Serialize(p),Encoding.UTF8);
    foreach(var part in parts.Parts){var mesh=PrintExport.Mesh(part);double error=Math.Abs(mesh.SignedVolume()/part.Volume()-1);Check(error<.01,"STL positive volume "+part.Id+" err="+error);using(var stream=new MemoryStream()){PrintExport.Stl(part,stream);byte[] bytes=stream.ToArray();Check(bytes.Length==84+50L*BitConverter.ToUInt32(bytes,80),"binary STL record sizes");}}
    if(kind==0){Check(!r.Model.Parts.Any(q=>q.Id.Contains("RING_ROLLER")||q.Id.Contains("ROLLER_AXLE")),"separate rollers/axes removed");var wall=parts.Parts.First(q=>q.Id.EndsWith("_CASE_WALL"));var hole=wall.Sections[0].Holes[0];Check(!hole.Circle&&wall.Sections.Count==1,"teeth belong to one wall extrusion");for(int j=0;j<r.Pins;j++){var v=Engine.Polar(p.Radius,Engine.Tau*j/r.Pins);Check(!hole.Contains(v.X,v.Y),"tooth in material");v=Engine.Polar(p.Radius-p.Roller/2-.15,Engine.Tau*j/r.Pins);Check(hole.Contains(v.X,v.Y),"free space before tooth");}StepExport.Write(PrintExport.Select(r.Model,new[]{wall.Id}),Path.Combine(folder,"integrated-ring-only.step"));using(var scene=new WpfScene()){scene.Root.Measure(new System.Windows.Size(1100,850));scene.Root.Arrange(new System.Windows.Rect(0,0,1100,850));scene.SetResult(r,false);foreach(var q in r.Model.Parts)if(q.Id!=wall.Id&&!q.Id.Contains("CYCLOID_DISC"))scene.Hidden.Add(q.Id);scene.RefreshVisibility();scene.Fit();scene.SavePng(Path.Combine(folder,"integrated-ring-and-discs.png"),1100,850);}}
    p.ExportScope=2;r.P=p;string scope=Path.Combine(folder,"scope-"+kind+".step");ReleaseSupport.Export(r,"step",scope);Check(File.ReadAllText(scope).Split(new[]{"MANIFOLD_SOLID_BREP("},StringSplitOptions.None).Length-1==parts.Parts.Count,"STEP print scope");foreach(string format in new[]{"csv","svg","dxf"})ReleaseSupport.Export(r,format,Path.Combine(folder,"scope-"+kind+"."+format));
    using(var dialog=new PrintDialog(r.Model)){Check(dialog.SelectedIds.Count==parts.Parts.Count&&dialog.StlZip,"selection dialog defaults");}
    log.AppendLine("PASS kind "+kind+": "+parts.Parts.Count+" printable parts out of "+r.Model.Parts.Count+"; ZIP/STL, filtered STEP/CSV/SVG/DXF; positive mesh volumes.");
   }
   foreach(bool ring in new[]{false,true})foreach(int preset in new[]{1,2,3,4})foreach(int ratio in new[]{8,20,60,120}){var p=Engine.Starter(0);p.RingOutput=ring;p.IntegratedRing=true;p.Ratio=ratio;Engine.SetPreset(p,preset);p.Overall=Math.Max(p.Overall,Math.Ceiling(p.Roller*Engine.PinCount(p)/Math.PI+2*p.Wall+25));Check(Engine.FitOverall(p),"fit "+ring+"/"+preset+"/"+ratio);var r=Engine.Calculate(p);r.Model=CadBuilder.Build(r);Check(r.Model.Valid,"integrated grid "+ring+"/"+preset+"/"+ratio+": "+string.Join(";",r.Model.Errors));Check(IntegratedRing.ClearsBridges(r,360),"bridge clearance 360 phases");if(!ring&&preset==2&&ratio==20){StepExport.Write(PrintExport.Select(r.Model,null),Path.Combine(folder,"standard-integrated.step"));}}
   foreach(int kind in new[]{0,3}){var p=Engine.Starter(kind);p.IntegratedRing=kind==0;p.RingOutput=false;if(kind==3){p.Ratio=60;p.Overall=222.82;}Engine.FitOverall(p);var r=Engine.Calculate(p);r.Model=CadBuilder.Build(r);Check(r.Model.Valid,"extra print case "+kind);var parts=PrintExport.Select(r.Model,null);string name=kind==0?"standard-integrated":"planet-60";PrintExport.Zip(parts,Path.Combine(folder,name+".zip"));StepExport.Write(parts,Path.Combine(folder,name+".step"));ReleaseSupport.WriteText(Path.Combine(folder,name+".gear.json"),ReleaseSupport.Serialize(p),Encoding.UTF8);log.AppendLine("PASS extra printable "+name+": "+parts.Parts.Count+" parts.");}
   var bad=Engine.Starter(0);bad.IntegratedRing=true;bad.RingBridge=bad.Roller;Check(!CadBuilder.Build(Engine.Calculate(bad)).Valid,"invalid bridge width rejected");var legacy=ReleaseSupport.Parse("{\"Kind\":0}");Check(!legacy.IntegratedRing&&legacy.RingBridge==0,"old files keep separate rollers");var round=Engine.Starter(0);round.IntegratedRing=true;round.RingBridge=1.2;round.ExportScope=2;var read=ReleaseSupport.Parse(ReleaseSupport.Serialize(round));Check(read.IntegratedRing&&read.RingBridge==1.2&&read.ExportScope==2,"new fields persist");
   using(var form=new MainForm(new TestDialogs()))form.PrintUiRegression(log);
   log.AppendLine("PASS "+checks+" assertions; 32 integrated ring/output/preset/ratio combinations, each with 360 sampled input phases and both discs. Sampling is not continuous collision certification.");File.WriteAllText(Path.Combine(folder,"print-results.txt"),log.ToString(),Encoding.UTF8);return 0;
  }catch(Exception ex){File.WriteAllText(Path.Combine(folder,"print-error.txt"),log+Environment.NewLine+ex,Encoding.UTF8);return 1;}}
 }
 public partial class MainForm {
  internal void PrintUiRegression(StringBuilder log){Opacity=0;ShowInTaskbar=false;Show();animation.Stop();Apply(Engine.Starter(0),true);integratedRing.Checked=true;if(!p.IntegratedRing||!result.Model.Valid||!VisibleField("RingBridge"))throw new Exception("integrated checkbox UI");integratedRing.Checked=false;if(p.IntegratedRing||!result.Model.Parts.Any(q=>q.Id.Contains("RING_ROLLER")))throw new Exception("legacy rollers UI");integratedRing.Checked=true;exportScope.SelectedIndex=2;if(p.ExportScope!=2||!print.Enabled||!step.Enabled)throw new Exception("print scope controls");numbers["RingBridge"].Commit((decimal)p.Roller);calculate.PerformClick();if(result.Model.Valid||print.Enabled||step.Enabled)throw new Exception("invalid printable geometry gate");numbers["RingBridge"].Commit(0);calculate.PerformClick();if(!result.Model.Valid||!print.Enabled)throw new Exception("auto bridge recovery");closingApproved=true;Close();log.AppendLine("PASS UI: integrated/legacy switch, print scope, bridge errors disable exports and recover with auto width.");}
 }
}
